     3	public class ClaimOffice {
     4	
     5	    private static final int PROCESSING_FEE_IN_G = 5;
     6	
     7	    private final PolicyWideModifiers policyWideModifiers;
     8	
     9	    public ClaimOffice(Customer customer) {
    10	        this.policyWideModifiers = new PolicyWideModifiers(customer);
    11	    }
    12	
    13	    /**
    14	     * The policy base premium is the sum of the base premiums of the main items
    15	     * and of the components, each priced by its own MHPCO pricing policy.
    16	     */
    17	    public int basePremium(List<Item> items) {
    18	        return MainItemPricing.mainItemsBasePremium(items)
    19	                + ComponentPricing.componentsBasePremium(items);
    20	    }
    21	
    22	    /**
    23	     * Item-specific modifiers apply to the base premium of the affected item,
    24	     * not to the policy total.
    25	     */
    26	    public int premiumAfterItemModifiers(List<Item> items) {
    27	        return basePremium(items) + ItemRiskSurcharges.totalItemSurcharges(items);
    28	    }
    29	
    30	    /**
    31	     * The MHPCO assembles a premium in a fixed order: the policy base premium,
    32	     * then the item-specific risk surcharges, then the policy-wide modifiers,
    33	     * and the processing fee at the very end.
    34	     */
    35	    public int quote(List<Item> items) {
    36	        int premium = premiumAfterItemModifiers(items);
    37	        int quotedPremium = premium
    38	                + policyWideModifiers.totalPolicyModifiers(premium)
    39	                + PROCESSING_FEE_IN_G;
    40	        policyWideModifiers.recordContractIssued();
    41	        return quotedPremium;
    42	    }
    43	}
