     1	/**
     2	 * The MHPCO's policy-wide premium modifiers. Unlike the item-specific risk
     3	 * surcharges, these are measured against the policy premium as a whole and
     4	 * depend on the customer's history with the MHPCO rather than on any item.
     5	 *
     6	 * This is the one place that says which modifiers are policy-wide: a further
     7	 * policy-wide modifier is added here and nowhere else. So far the MHPCO grants
     8	 * the loyalty discount and charges the initial assessment surcharge.
     9	 */
    10	public final class PolicyWideModifiers {
    11	
    12	    private static final int LOYALTY_YEARS = 2;
    13	
    14	    private static final int LOYALTY_DISCOUNT_PERCENT = 20;
    15	
    16	    private static final int INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
    17	
    18	    private static final int FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
    19	
    20	    private final Customer customer;
    21	
    22	    private int contractsIssued;
    23	
    24	    public PolicyWideModifiers(Customer customer) {
    25	        this.customer = customer;
    26	    }
    27	
    28	    /**
    29	     * The net effect of every policy-wide modifier on a policy premium:
    30	     * positive amounts are charged to the customer, negative amounts are
    31	     * granted to the customer. Each modifier states its own direction, so this
    32	     * sum says only which modifiers the MHPCO applies policy-wide.
    33	     */
    34	    public int totalPolicyModifiers(int policyPremium) {
    35	        return initialAssessmentSurcharge(policyPremium)
    36	                + loyaltyDiscount(policyPremium)
    37	                + followUpContractDiscount(policyPremium);
    38	    }
    39	
    40	    /**
    41	     * The MHPCO notes that a contract has been issued to this customer. Every
    42	     * later contract is a follow-up contract, which is what the follow-up
    43	     * contract discount is measured against.
    44	     */
    45	    public void recordContractIssued() {
    46	        contractsIssued++;
    47	    }
    48	
    49	    /**
    50	     * Customers receive a 15 % discount on each contract after their first.
    51	     */
    52	    private int followUpContractDiscount(int policyPremium) {
    53	        if (!hasAPreviousContract()) {
    54	            return 0;
    55	        }
    56	        return -(policyPremium * FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT / 100);
    57	    }
    58	
    59	    private boolean hasAPreviousContract() {
    60	        return contractsIssued > 0;
    61	    }
    62	
    63	    /**
    64	     * Long-standing customers -- 2 or more years of business with the MHPCO --
    65	     * receive a 20 % loyalty discount on the policy premium.
    66	     */
    67	    private int loyaltyDiscount(int policyPremium) {
    68	        if (!isLongStandingCustomer()) {
    69	            return 0;
    70	        }
    71	        return -(policyPremium * LOYALTY_DISCOUNT_PERCENT / 100);
    72	    }
    73	
    74	    /**
    75	     * The MHPCO counts a customer as long-standing from 2 full years of
    76	     * business onwards; a customer in their second year is still a newcomer.
    77	     */
    78	    private boolean isLongStandingCustomer() {
    79	        return customer.yearsWithMHPCO() >= LOYALTY_YEARS;
    80	    }
    81	
    82	    /**
    83	     * Every item in a quote is treated as a first insurance, regardless of the
    84	     * customer's history with the MHPCO, and carries a 10 % initial assessment
    85	     * surcharge on the policy premium.
    86	     */
    87	    private int initialAssessmentSurcharge(int policyPremium) {
    88	        return policyPremium * INITIAL_ASSESSMENT_SURCHARGE_PERCENT / 100;
    89	    }
    90	
    91	}

